group('UT-wording — no "summary"/"concise" cognates (AC8, six files)', () {
  test('all compaction prompt bodies are cognate-free and assert '
      'lossless handoff', () {
    final bodies = [
      _promptBody('prompts/compaction/summary.md'),
      _promptBody('prompts/compaction/summary_update.md'),
      _promptBody('prompts/compaction/summary_system.md'),
      _promptBody('prompts/compaction/branch_summary.md'),
      _promptBody('prompts/compaction/branch_summary_preamble.md'),
      _promptBody('prompts/compaction/turn_prefix.md'),
    ];
    for (final body in bodies) {
      expect(
        RegExp('summar|concis', caseSensitive: false).allMatches(body),
        isEmpty,
        reason: '"summary"/"concise" cognates license dropping facts',
      );
    }
    expect(bodies[0], contains('Preserve EVERY fact'));
  });
});

group('IT-compaction — the ask lands in the checkpoint (AC1)', () {
  test(
    'generateSummary appends the candidates block and section prompt',
    () async {
      final fake = _FakeSummarizer([
        SummarizationResult.success(
          '## Goal\nx\n\n## Open User Requests\n'
          '- [ ] Build the browser extension (asked 2026-09-02)\n',
        ),
      ]);
      final summary = await generateSummary([_ask()], summarize: fake.call);
      final prompt = fake.prompts.single;
      expect(prompt, contains('## Open User Requests'));
      expect(prompt, contains('USER REQUEST CANDIDATES'));
      expect(prompt, contains('- [asked 2026-09-02] Build the browser'));
      // Block sits between the conversation and the instructions.
      expect(
        prompt.indexOf('</conversation>'),
        lessThan(prompt.indexOf('USER REQUEST CANDIDATES')),
      );
      expect(summary, contains('## Open User Requests'));
    },
  );

  test('no user words — no candidates block, prompt stays lean', () async {
    final fake = _FakeSummarizer([SummarizationResult.success('## Goal\nx')]);
    await generateSummary([
      _assistant('working'),
      UserMessage.text(
        '<system-notice>background job finished: build ok</system-notice>',
      ),
    ], summarize: fake.call);
    expect(fake.prompts.single, isNot(contains('USER REQUEST CANDIDATES')));
  });

  test(
    'a marker-less ask lands in ## Open User Requests (#86 AC1)',
    () async {
      final summarizer = _RuleHonoringSummarizer();
      const ask = 'можешь глянуть почему тест падает?';
      final summary = await generateSummary([
        UserMessage.text(ask, timestamp: DateTime.utc(2026, 9, 2)),
      ], summarize: summarizer.call);
      expect(_candidateLines(summarizer.prompts.single), hasLength(1));
      expect(_openSection(summary), contains('- [ ] $ask'));
    },
