      if (result.aborted) return null;
      if (result.summary != null) {
        summary = result.summary;
        details = {
          'readFiles': result.readFiles ?? const <String>[],
          'modifiedFiles': result.modifiedFiles ?? const <String>[],
        };
      }
    }
  }
  return session.moveTo(
    targetId,
    summary: summary,
    details: details,
    fromHook: fromHook,
  );
}

